INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein lokales Rechenzentrum immer teurer als Cloud-Lösungen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten variieren je nach Einsatz"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein lokales Rechenzentrum für ein Unternehmen plane?', 3, '[{"text": "Datensicherheit", "correct": true, "because": "Schützt sensible Daten"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem lokalen Rechenzentrum?', 5, '[{"text": "Server", "correct": true, "because": "Verarbeiten Daten"}, {"text": "Kühlsysteme", "correct": true, "because": "Verhindern Überhitzung"}, {"text": "Büromöbel", "correct": false, "because": "Kein IT-Fokus"}, {"text": "Marketingmaterial", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein lokales Rechenzentrum bietet direkte Kontrolle. b) Es ist immer langsamer als Cloud-Lösungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein lokales Rechenzentrum für ein Unternehmen plane?', 4, '[{"text": "Stromversorgung", "correct": false, "because": "Entscheidend für Betrieb"}, {"text": "Netzwerkanbindung", "correct": false, "because": "Sichert Datenfluss"}, {"text": "Bürofarben", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein lokales Rechenzentrum immer eine Internetverbindung braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch offline nutzbar"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem lokalen Rechenzentrum?', 3, '[{"text": "Datenkontrolle", "correct": true, "because": "Sichert Souveränität"}, {"text": "Geringste Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein lokales Rechenzentrum effektiv?', 5, '[{"text": "Redundante Stromversorgung", "correct": true, "because": "Sichert Betrieb"}, {"text": "Effiziente Kühlung", "correct": true, "because": "Schützt Hardware"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Lokale Rechenzentren bieten mehr Sicherheit als Clouds. b) Sie sind immer wartungsintensiv. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein lokales Rechenzentrum?', 4, '[{"text": "Serverracks", "correct": false, "because": "Aufbau notwendig"}, {"text": "Netzwerkswitches", "correct": false, "because": "Sichern Konnektivität"}, {"text": "Bürodeko", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein lokales Rechenzentrum immer schneller als eine Cloud?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Netzwerk"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein lokales Rechenzentrum?', 4, '[{"text": "Direkte Kontrolle", "correct": true, "because": "Sichert Daten"}, {"text": "Geringe Latenz", "correct": true, "because": "Lokale Verarbeitung"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass lokale Rechenzentren nur für große Firmen geeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMU nutzen sie"}, {"text": "Ja", "correct": false, "because": "Skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein lokales Rechenzentrum für ein Unternehmen zu optimieren?', 3, '[{"text": "Redundanzsysteme", "correct": true, "because": "Sichert Ausfallsicherheit"}, {"text": "Billige Hardware", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Kabel", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lokale Rechenzentren erhöhen die Datensicherheit. b) Sie sind immer wartungsfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem lokalen Rechenzentrum?', 5, '[{"text": "Kühlung", "correct": true, "because": "Schützt Hardware"}, {"text": "Stromversorgung", "correct": true, "because": "Sichert Betrieb"}, {"text": "Bürogröße", "correct": false, "because": "Sekundär"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein lokales Rechenzentrum plane?', 3, '[{"text": "Netzwerkleistung", "correct": false, "because": "Entscheidend für Datenfluss"}, {"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Schützen Daten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein lokales Rechenzentrum immer unabhängig von externen Diensten?', 3, '[{"text": "Nein", "correct": true, "because": "Kann Internet nutzen"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob lokale Rechenzentren mehr Kontrolle als Clouds bieten?', 2, '[{"text": "Ja", "correct": true, "because": "Direkte Verwaltung"}, {"text": "Nein", "correct": false, "because": "Kontrolle ist Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für ein lokales Rechenzentrum?', 4, '[{"text": "Ausfallsicherheit", "correct": true, "because": "Sichert Betrieb"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]');
